//! Build-only release staging; Cargo does not install examples.
#[path = "../src/release_smoke.rs"]
mod release_smoke;

use provenant_core::{CancelToken, PathResolver};
use provenant_records::{SourceDigest, VersionInfo};

use std::{
    env,
    ffi::OsStr,
    fs,
    io::{self, Write},
    path::{Component, Path, PathBuf},
};

// Generated by the same build-script pass that stamps the asset digest.
include!(concat!(env!("OUT_DIR"), "/release_assets.rs"));

fn output_directory(output: &Path) -> io::Result<PathBuf> {
    if !output.is_absolute()
        || output
            .components()
            .any(|part| matches!(part, Component::ParentDir))
    {
        return Err(io::Error::other(
            "--out must be an absolute path without ..",
        ));
    }
    let output =
        PathResolver::resolve_existing_ancestor(&provenant_os::fs::SystemPathResolver, output)?;
    let checkout = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .ok_or_else(|| io::Error::other("cannot resolve build checkout"))?
        .canonicalize()?;
    if output.starts_with(checkout) {
        return Err(io::Error::other(
            "--out must be outside the repository checkout",
        ));
    }
    for parent in output.ancestors() {
        if parent.join(".git").try_exists()? {
            return Err(io::Error::other(
                "--out must be outside repository checkouts",
            ));
        }
    }
    if output.try_exists()? {
        return Err(io::Error::other(
            "--out already exists; choose a fresh directory",
        ));
    }
    Ok(output)
}

fn require_current_source(identity: &VersionInfo, current: &SourceDigest) -> io::Result<()> {
    if &identity.source_digest == current {
        Ok(())
    } else {
        Err(io::Error::other(
            "release binary source digest differs from the current workspace; rebuild it",
        ))
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut args = env::args_os().skip(1);
    let mut output = None;
    let mut binary = None;
    while let Some(arg) = args.next() {
        match arg.as_os_str() {
            value if value == OsStr::new("--out") => {
                output = Some(PathBuf::from(
                    args.next().ok_or("--out needs an absolute path")?,
                ));
            }
            value if value == OsStr::new("--binary") => {
                binary = Some(PathBuf::from(args.next().ok_or("--binary needs a path")?));
            }
            value if value == OsStr::new("--help") => {
                writeln!(
                    io::stdout().lock(),
                    "cargo run --example package-release -- --out ABS [--binary PATH]"
                )?;
                return Ok(());
            }
            _ => return Err("usage: package-release --out ABS [--binary PATH]".into()),
        }
    }
    let output = output_directory(&output.ok_or("--out ABS is required")?)?;
    let binary = binary
        .unwrap_or_else(|| {
            env::var_os("CARGO_TARGET_DIR")
                .map(PathBuf::from)
                .unwrap_or_else(|| Path::new(env!("CARGO_MANIFEST_DIR")).join("target"))
                .join("release/provenant")
        })
        .canonicalize()?;
    let smoke = release_smoke::SystemSmoke::new(None)?;
    let cancel = CancelToken::new();
    let identity = smoke.identity(&binary, &cancel)?;
    let current_source = SourceDigest::parse(env!("PROVENANT_SOURCE_DIGEST"))?;
    require_current_source(&identity, &current_source)?;
    // Never overwrite a previous stage. A failed stage has no completion marker;
    // preserve it for inspection and ask the caller to choose a fresh directory.
    fs::create_dir(&output)?;
    fs::create_dir(output.join("bin"))?;
    fs::copy(binary, output.join("bin/provenant"))?;
    for &(source, name) in RELEASE_ASSETS {
        let destination = output.join(name);
        fs::create_dir_all(destination.parent().ok_or("release asset has no parent")?)?;
        fs::copy(source, destination)?;
    }
    let release = provenant_config::package_release(&output, &identity, &smoke, &cancel)?;
    writeln!(
        io::stdout().lock(),
        "Packaged {} files: {}\nSource digest: {}",
        release.manifest().files.len(),
        output.display(),
        identity.source_digest
    )?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::{fs, os::unix::fs::symlink};

    #[test]
    fn packaging_refuses_a_binary_with_an_older_source_digest()
    -> Result<(), Box<dyn std::error::Error>> {
        let old = VersionInfo {
            source_digest: SourceDigest::parse(&format!("sha256:{}", "0".repeat(64)))?,
            asset_digest: SourceDigest::parse(&format!("sha256:{}", "1".repeat(64)))?,
            target: "test-target".into(),
            toolchain: "test-toolchain".into(),
            record_schema_version: 1,
            config_schema_version: 1,
        };
        let current = SourceDigest::parse(&format!("sha256:{}", "2".repeat(64)))?;
        assert!(require_current_source(&old, &current).is_err());
        Ok(())
    }

    #[test]
    fn staging_refuses_checkout_aliases_and_existing_outputs()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = tempfile::tempdir()?;
        let root = fs::canonicalize(temporary.path())?;
        let checkout = root.join("checkout");
        fs::create_dir_all(checkout.join(".git"))?;
        let alias = root.join("alias");
        symlink(&checkout, &alias)?;
        let existing = root.join("existing");
        fs::create_dir(&existing)?;
        for output in [checkout.join("release"), alias.join("release"), existing] {
            assert!(output_directory(&output).is_err(), "{}", output.display());
            assert!(!output.join("release.json").exists());
        }
        let fresh = root.join("release");
        assert_eq!(output_directory(&fresh)?, fresh);
        assert!(!fresh.exists());
        Ok(())
    }
}
